files.style.css:
:root { color-scheme: dark; font-family: system-ui, sans-serif; }
body { min-height: 100vh; margin: 0; display: grid; place-items: center; background: [[AXM:background]]; color: #f7f8ff; }
main { width: min(42rem, calc(100% - 2rem)); }
button { padding: .8rem 1rem; border: 0; border-radius: 999px; }
